try {
    var data = JSON.parse(msg.payload);

    if (data.topic === '/map') {
        if (data.msg && data.msg.info) {
            var info = data.msg.info;
            flow.set('map_width', info.width);
            flow.set('map_height', info.height);
            flow.set('map_resolution', info.resolution);
            flow.set('map_origin_x', info.origin.position.x);
            flow.set('map_origin_y', info.origin.position.y);
            flow.set('map_data', data.msg.data);
        }
        // Send full map payload to canvas
        msg.payload = {
            type: 'map',
            width: flow.get('map_width') || 0,
            height: flow.get('map_height') || 0,
            resolution: flow.get('map_resolution') || 0.05,
            origin_x: flow.get('map_origin_x') || 0,
            origin_y: flow.get('map_origin_y') || 0,
            data: flow.get('map_data') || [],
            robot_x: flow.get('robot_x') || 0,
            robot_y: flow.get('robot_y') || 0,
            robot_yaw: flow.get('robot_yaw') || 0
        };
        return [msg, null];

    } else if (data.topic === '/amcl_pose') {
        if (data.msg && data.msg.pose && data.msg.pose.pose) {
            var pose = data.msg.pose.pose;
            var rx = pose.position.x;
            var ry = pose.position.y;
            var qz = pose.orientation.z;
            var qw = pose.orientation.w;
            var yaw = Math.atan2(2.0 * qw * qz, 1.0 - 2.0 * qz * qz);
            flow.set('robot_x', rx);
            flow.set('robot_y', ry);
            flow.set('robot_yaw', yaw);
            msg.payload = {
                type: 'pose',
                robot_x: rx,
                robot_y: ry,
                robot_yaw: yaw
            };
            return [null, msg];
        }
    }
    return [null, null];
} catch(e) {
    return [null, null];
}

if (!msg.payload || !msg.payload.waypoints) return null;
var wps = [];
var raw = msg.payload.waypoints;
for (var name in raw) {
  wps.push({name: name, x: raw[name].x, y: raw[name].y, yaw: raw[name].yaw || 0});
}
msg.payload = {type: 'waypoints', waypoints: wps, nav_target: msg.payload.nav_target || null};
return msg;

if (flow.get('arm_enabled') === true) {
    return msg;
